import java.util.Scanner;

public class Main {
  public static void main(String[] args) {
    Scanner scanner = new Scanner(System.in);
    long n = scanner.nextLong();
    long result = decompose(n);
    System.out.println(result);
  }

  public static long decompose(long n) {
    if (n <= 6) {
      return n;
    }
    long numDigits = getNumOfDigits(n);
    long lower = getOnes(numDigits);
    long upper;
    if (n < lower) {
      upper = getOnes(numDigits + 1);
    } else if (n > lower) {
      upper = getOnes(numDigits + 1);
    } else {
      return numDigits;
    }
    long resLower = decompose(n % lower) + (n / lower) * getOnes(numDigits);
    long resUpper = Long.MAX_VALUE;
    if (upper - n < n) {
      resUpper = decompose(upper - n) + getOnes(numDigits + 1);
    }
    return Math.min(resLower, resUpper);
  }

  public static long getNumOfDigits(long n) {
    return (long) Math.floor(Math.log10(n)) + 1;
  }

  public static long getOnes(long count) {
    long res = 0;
    for (int i = 0; i < count; i++) {
      res = res * 10 + 1;
    }
    return res;
  }
}
